        CategoryTheory.Projective.{v, u}
          (HomologicalComplex.X.{v, u, u_1} (CategoryTheory.ShortComplex.X₃.{max u_1 v, max (max u u_1) v} SC) i)) →
      CategoryTheory.ShortComplex.ShortExact.{max u_1 v', max (max u' u_1) v'}
        (CategoryTheory.ShortComplex.map.{max u_1 v, max (max u u_1) v, max u_1 v', max (max u' u_1) v'} SC
          (CategoryTheory.Functor.mapHomologicalComplex.{u_1, v, u, v', u'} F c))
